def find_groups_and_gaps(row_or_col_data):
    """
    row_or_col_data: sorted list of positions where there are sources
    Returns list of (group, gaps), where each gap is a range of positions to fill
    """
    groups = []
    if not row_or_col_data:
        return [], []

    current_group = [row_or_col_data[0]]
    for pos in row_or_col_data[1:]:
        if pos == current_group[-1] + 1:
            current_group.append(pos)
        else:
            groups.append(current_group)
            current_group = [pos]
    groups.append(current_group)

    # Find gaps
    gaps = []
    for i in range(len(groups)):
        if i < len(groups) - 1:
            gap_start = groups[i][-1] + 1
            gap_end = groups[i+1][0] - 1
            if gap_start <= gap_end:
                gaps.append(list(range(gap_start, gap_end + 1)))

    return groups, gaps

def compute_transform(grid):
    """
    Rule: For each row and column, find groups of adjacent sources.
    Fill gaps between groups with 2s.
    """
    arr = np.asarray(grid)
    bg = int(np.argmax(np.bincount(arr.flatten() + 1))) - 1

    H, W = arr.shape
    out = arr.copy()

    # For each row
    for r in range(H):
        sources = sorted([c for c in range(W) if arr[r, c] != bg])
        groups, gaps = find_groups_and_gaps(sources)
        for gap in gaps:
            for c in gap:
                out[r, c] = 2

    # For each column
    for c in range(W):
        sources = sorted([r for r in range(H) if arr[r, c] != bg])
        groups, gaps = find_groups_and_gaps(sources)
        for gap in gaps:
            for r in gap:
                out[r, c] = 2

    return out

with open(f"{workspace}/programs/{task_id}.json", 'r') as f:
    demos = json.load(f)

print("Testing group-gap filling transform:\n")
all_pass = True
